import { OrderRepository, ProductRepository } from '../domain/Repository';

export class CancelOrderUseCase {
  constructor(
    private orderRepository: OrderRepository,
    private productRepository: ProductRepository
  ) {}

  execute(orderId: string): void {
    const order = this.orderRepository.findById(orderId);
    if (!order) throw new Error(`Order ${orderId} not found`);

    const currentState = order.getState();
    if (currentState === 'shipped' || currentState === 'delivered') {
      throw new Error(`Cannot cancel order in state ${currentState}`);
    }

    for (const item of order.items) {
      const product = this.productRepository.findById(item.productId);
      if (product) {
        product.release(item.quantity);
      }
    }

    order.transitionTo('cancelled');
    this.orderRepository.save(order);
  }
}

